parameters.jsCode:
// Read-only step: get the watermark used for the next ERP fetch.
// The webhook can override via body.updated_since; the scheduled run uses workflow static data.
const staticData = $getWorkflowStaticData('global');
const fromItem = $input.first()?.json ?? {};
const override = fromItem.updated_since ?? fromItem.body?.updated_since;
const watermark = override || staticData.lastSyncedAt || '1970-01-01T00:00:00Z';
return [{ json: { updated_since: watermark } }];

// Explode: one n8n item per tenant row.
const payload = $input.first().json;
const rows = payload.huurders ?? [];
return rows.map(r => ({ json: r }));

// Map ERP (Dutch, NL locale) -> canonical platform schema. See docs/mapping.md.
// Output ONE item per input row. On failure, set $json._invalid with a rejection code so the IF node can split.
const STATUS = { actief: 'active', beeindigd: 'ended', 'beëindigd': 'ended' };

function stripToDigits(s) { return (s || '').replace(/\D+/g, ''); }
function parseDutchAmount(s) {
  if (s == null) return NaN;
  const t = String(s).trim().replace(/[^0-9,.\-]/g, '');
  // Thousands dot, decimal comma: "1.250,00" -> "1250.00"
  return Number(t.replace(/\./g, '').replace(',', '.'));
}
function parseDDMMYYYY(s) {
  if (!s) return null;
  const m = String(s).match(/^(\d{2})-(\d{2})-(\d{4})$/);
  if (!m) return null;
  const [_, dd, mm, yyyy] = m;
  const iso = `${yyyy}-${mm}-${dd}`;
  const d = new Date(iso + 'T00:00:00Z');
  if (Number.isNaN(d.getTime())) return null;
  // Reject rolls like 32-01-2024 by round-tripping.
  if (d.toISOString().slice(0, 10) !== iso) return null;
  return iso;
}

const out = [];
for (const item of $input.all()) {
  const r = item.json;
  const errors = [];

  const name = (r.naam ?? '').toString().trim();
  if (!name) errors.push('missing_name');

  const kvk = stripToDigits(r.kvk_nummer);
  if (!/^\d{8}$/.test(kvk)) errors.push('invalid_kvk');

  const leaseStart = parseDDMMYYYY(r.contract_start);
  if (!leaseStart) errors.push('invalid_date');

  const rent = parseDutchAmount(r.maandhuur);
  if (!Number.isFinite(rent) || rent < 0) errors.push('invalid_amount');

  const canonicalStatus = STATUS[(r.status ?? '').toString().toLowerCase()];
  if (!canonicalStatus) errors.push('unknown_status');

  if (errors.length) {
    out.push({ json: { _invalid: true, _codes: errors, source_row: r } });
    continue;
  }

  out.push({
    json: {
      _invalid: false,
      external_id: r.huurder_id,
      name,
      chamber_of_commerce_id: kvk,
      unit: r.unit_code,
      lease_start: leaseStart,
      monthly_rent_eur: rent,
      status: canonicalStatus,
      _gewijzigd_op: r.gewijzigd_op,
      source_row: r,
    },
  });
}
return out;

