parameters.jsCode:
// After the POST we always continue (neverError=true). Classify the response:
//   2xx: upserted; update watermark high-watermark.
//   4xx (409 / 422): persistent, report to integration-errors.
//   429 / 5xx after retries: report as transient.
const item = $input.first().json;
const status = item.statusCode ?? item.status ?? 0;
const body = item.body ?? item;
if (status >= 200 && status < 300) {
  return [{ json: { ok: true, external_id: body.external_id, gewijzigd_op: $('Map & validate').item?.json?._gewijzigd_op } }];
}
let code = 'platform_422';
if (status === 409) code = 'external_id_conflict';
else if (status === 429) code = 'rate_limit';
else if (status >= 500) code = 'platform_5xx';
const source = $('Map & validate').item.json.source_row;
return [{ json: { ok: false, source: 'erp-to-platform-tenant-sync', http_status: status,
                   error_body: JSON.stringify(body), payload: source, code } }];

// Build a report body for /platform/v1/integration-errors.
// Works both for validation-rejected rows (from the Valid? false branch)
// and HTTP failures (from Classify response).
const j = $json;
const payload = j.source_row ? j.source_row : j.payload;
const http_status = j.http_status ?? (j._invalid ? 422 : null);
const error_body = j._invalid
  ? JSON.stringify({ error: 'validation', codes: j._codes })
  : (j.error_body || '');
return [{ json: {
  source: 'WF1: erp-to-platform-tenant-sync',
  payload,
  http_status,
  error_body,
} }];

// Watermark advance: when at least one row upserted OK, set lastSyncedAt to the max
// gewijzigd_op of the successful rows. Rejected rows do NOT advance the watermark
// so they re-queue on the next run (and get re-reported as 'duplicate' events on the error log).
const staticData = $getWorkflowStaticData('global');
let maxWm = staticData.lastSyncedAt || '1970-01-01T00:00:00Z';
for (const it of $input.all()) {
  const t = it.json.gewijzigd_op;
  if (t && t > maxWm) maxWm = t;
}
staticData.lastSyncedAt = maxWm;
return [{ json: { watermark_now: maxWm, count: $input.all().length } }];
